package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#addValue(Object)
 */
public class Frequency_addValue_TriageGen4Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testAddValueWithInteger() {
        Integer value = 10;
        frequency.addValue(value);

        assertEquals("Count should be 1 for the added integer", 1L, frequency.getCount(value));
        assertEquals("Sum frequency should be 1", 1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValueWithString() {
        String value = "test";
        frequency.addValue(value);

        assertEquals("Count should be 1 for the added string", 1L, frequency.getCount(value));
        assertEquals("Sum frequency should be 1", 1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValueMultipleTimes() {
        Integer value1 = 1;
        Integer value2 = 2;

        frequency.addValue(value1);
        frequency.addValue(value1);
        frequency.addValue(value2);

        assertEquals("Count for value1 should be 2", 2L, frequency.getCount(value1));
        assertEquals("Count for value2 should be 1", 1L, frequency.getCount(value2));
        assertEquals("Total sum frequency should be 3", 3L, frequency.getSumFreq());
    }

    @Test(expected = ClassCastException.class)
    public void testAddValueWithNonComparableObject() {
        // Non-comparable object to trigger ClassCastException during (Comparable<?>) cast
        Object nonComparable = new Object();
        frequency.addValue(nonComparable);
    }

    @Test
    public void testAddValueWithNull() {
        // Depending on the implementation of addValue(Comparable<?> v), 
        // null might be allowed or throw NullPointerException. 
        // Given the cast, it passes null to the next method.
        frequency.addValue(null);
        assertEquals("Count for null should be 1", 1L, frequency.getCount(null));
        assertEquals("Sum frequency should be 1", 1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValueWithDouble() {
        // Double implements Comparable
        Double value = 10.5;
        frequency.addValue(value);

        assertEquals("Count should be 1 for the added double", 1L, frequency.getCount(value));
        assertEquals("Sum frequency should be 1", 1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValueWithChar() {
        Character value = 'A';
        frequency.addValue(value);

        assertEquals("Count should be 1 for the added char", 1L, frequency.getCount(value));
        assertEquals("Sum frequency should be 1", 1L, frequency.getSumFreq());
    }
}
